// Swift async is a compiler state machine; withTaskGroup is structured concurrency.
func handle(id: String) async throws -> Result {
    // async let: both start concurrently and are awaited before the function returns
    async let user   = fetchUser(id)
    async let orders = fetchOrders(id)
    return try await Result(user: user, orders: orders)   // a child's failure cancels the other
}

func handleAll(_ ids: [String]) async throws -> [Result] {
    try await withThrowingTaskGroup(of: Result.self) { group in   // structured: bounded
        for id in ids { group.addTask { try await handle(id) } }
        return try await group.reduce(into: [Result]()) { $0.append($1) }
    }
}

// Task { } launches at the top level (unstructured: NOT cancelled with the caller).
// An actor method that AWAITS between two mutations releases isolation at the
// await, so another message can interleave - the same hazard as function colouring.
